row1 {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 8px;
  margin-bottom: 4px;

overview {
  display: flex;
  flex-direction: row;
  gap: 8px;
  align-items: flex-start;
  margin-bottom: 12px;
}

.status-overview__left {
  display: flex;
  flex-direction: column;
  gap: 8px;
  flex: 1;
  min-width: 0;
}

.status-overview__availability {
  min-width: 0;
}

.status-row1__cards {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.mini-date-calendar {
  width: 250px;
  border: 1px solid #cfd7e3;
  background:
    linear-gradient(180deg, #ffffff 0%, #f9fbfe 100%);
  box-shadow: 0 10px 24px rgba(28, 42, 62, 0.06);
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.mini-date-calendar__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 5px 10px;
  border-bottom: 1px solid #dbe2ec;
  background: linear-gradient(180deg, #f7f9fc 0%, #f1f5fa 100%);
}

.mini-date-calendar__eyebrow {
  margin-bottom: 3px;
  font-size: 11px;
  font-weight: 700;
  color: #6c7a8c;
}

.mini-date-calendar__header strong {
  display: block;
  font-size: 17px;
  line-height: 1;
  color: #243446;
}

.mini-date-calendar__controls {
  display: flex;
  gap: 4px;
}

.mini-date-calendar__nav,
.mini-date-calendar__today {
  border: 1px solid #ccd6e2;
  background: #fff;
  color: #36485c;
  cursor: pointer;
  font-size: 11px;
  font-weight: 700;
}

.mini-date-calendar__nav {
  width: 28px;
  height: 28px;
  padding: 0;
}

.mini-date-calendar__weekdays,
.mini-date-calendar__grid {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
}

.mini-date-calendar__weekdays {
  padding: 8px 8px 0;
}

.mini-date-calendar__weekday {
  text-align: center;
  font-size: 12px;
  font-weight: 700;
  color: #43566c;
  padding-bottom: 6px;
}

.mini-date-calendar__weekday.is-sunday {
  color: #d44a3e;
}

.mini-date-calendar__weekday.is-saturday {
  color: #2b63c6;
}

.mini-date-calendar__grid {
  gap: 1px;
  padding: 0 8px 8px;
  background: #dfe6ef;
}

.mini-date-calendar__day {
  appearance: none;
  border: 0;
  min-height: 40px;
  padding: 0;
  background: #fff;
  color: #334155;
  font-size: 15px;
  cursor: pointer;
  position: relative;
}

.mini-date-calendar__day>span {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
}

.mini-date-calendar__day.is-outside {
  color: #9aa8b7;
  background: #f7f9fc;
}

.mini-date-calendar__day.is-sunday {
  color: #d44a3e;
}

.mini-date-calendar__day.is-holiday {
  color: #d44a3e;
}

.mini-date-calendar__day.is-saturday {
  color: #2b63c6;
}

.mini-date-calendar__day.is-outside.is-sunday,
.mini-date-calendar__day.is-outside.is-saturday {
  color: #9aa8b7;
}

.mini-date-calendar__day:hover {
  background: #eef4fb;
}

.mini-date-calendar__day.is-today {
  box-shadow: inset 0 0 0 1px #8cb1dd;
  font-weight: 700;
}

.mini-date-calendar__day.is-selected {
  background: #2f5e97;
  color: #fff;
  font-weight: 700;
  box-shadow: inset 0 0 0 1px #234876;
}

.mini-date-calendar__day.is-selected.is-sunday,
.mini-date-calendar__day.is-selected.is-holiday,
.mini-date-calendar__day.is-selected.is-saturday,
.mini-date-calendar__day.is-selected.is-outside {
  color: #fff;
}

.mini-date-calendar__footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 10px 12px 12px;
  border-top: 1px solid #dbe2ec;
  background: linear-gradient(180deg, #fbfcfe 0%, #f4f7fb 100%);
}

.mini-date-calendar__selected-date {
  font-size: 12px;
  font-weight: 700;
  color: #4c5d71;
}

.mini-date-calendar__today {
  padding: 5px 10px;
}

@media (max-width: 1200px) {
  .status-overview {
    grid-template-columns: 1fr;
  }

  .mini-date-calendar {
    max-width: 360px;
  }
}

@media (max-width: 900px) {
  .status-row1__cards {
    grid-template-columns: 1fr;
  }

  .mini-date-calendar {
    max-width: none;
  }

